package com.doms.doms.serviceImpl;import com.doms.doms.entity.*;import com.doms.doms.repository.AuditLogRepository;import com.doms.doms.service.AuditService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class AuditServiceImpl implements AuditService{private final AuditLogRepository logs;public void record(User u,Document d,String action,String details){logs.save(AuditLog.builder().user(u).documentId(d==null?null:d.getId()).documentCode(d==null?null:d.getDocumentCode()).documentName(d==null?null:d.getFileName()).action(action).details(details).createdAt(LocalDateTime.now()).build());}}
